input_script:
var boardRequest = input.query || input || {};
var boardProjects = Array.isArray(boardRequest.projects) ? boardRequest.projects : (boardRequest.projects ? [boardRequest.projects] : []);
var boardScopes = [];
for (var bs = 0; bs < boardProjects.length; bs++) {
  var bp = boardProjects[bs];
  if (!bp) continue;
  var bk = typeof bp === 'object' ? String(bp.jiraproject || '').trim() : '';
  var bn = typeof bp === 'string' ? bp.trim() : String(bp.projectname || '').trim();
  if (!bk && !bn) continue;
  boardScopes.push({project_key: bk, project_name: bn,
    board_id: typeof bp === 'object' ? String(bp.boardid || '').trim() : '',
    connection_id: String((typeof bp === 'object' && bp.connectionid) || boardRequest.connectionid || '').trim()});
}

var scopeRequest = input.query || input || {};
var scopeProjects = Array.isArray(scopeRequest.projects) ? scopeRequest.projects : (scopeRequest.projects ? [scopeRequest.projects] : []);
var projectKeys = [];
for (var si = 0; si < scopeProjects.length; si++) {
  var sp = scopeProjects[si];
  var sk = typeof sp === 'object' && sp !== null ? String(sp.jiraproject || '').trim() : '';
  if (sk && projectKeys.indexOf(sk) < 0) projectKeys.push(sk);
}
var hasIssueScope = 0;
for (var scopeIndex = 0; scopeIndex < scopeProjects.length; scopeIndex++) {
  var scopeProject = scopeProjects[scopeIndex];
  if (typeof scopeProject === 'string' && scopeProject.trim()) hasIssueScope = 1;
  if (scopeProject && typeof scopeProject === 'object' &&
      (String(scopeProject.projectname || '').trim() || String(scopeProject.jiraproject || '').trim())) hasIssueScope = 1;
}
if (projectKeys.length === 0) projectKeys = ['__NONE__'];

var projects = Array.isArray(input.projects) ? input.projects : (input.projects ? [input.projects] : []);
var excludeProjects = Array.isArray(input.excludeProjects) ? input.excludeProjects : [];
var from = Number(input.from) || 0;
var to = Number(input.to) || 0;

var rawWhitelist = input.userwhitelist;
var userwhitelist = [];
if (Array.isArray(rawWhitelist)) {
  userwhitelist = rawWhitelist;
} else if (rawWhitelist && typeof rawWhitelist === 'object') {
  for (var key in rawWhitelist) {
    if (rawWhitelist.hasOwnProperty(key)) {
      userwhitelist.push(rawWhitelist[key]);
    }
  }
}

var validProjects = [];
var projectFilters = [];
for (var i = 0; i < projects.length; i++) {
  var p = projects[i];
  var name = '';
  if (typeof p === 'string') {
    name = p.trim();
  } else if (typeof p === 'object' && p !== null) {
    name = (p.projectname || '').trim();
  }
  if (name === '') continue;
  validProjects.push(name);

  var components = (typeof p === 'object' && Array.isArray(p.components)) ? p.components : [];
  var labels = (typeof p === 'object' && Array.isArray(p.labels)) ? p.labels : [];
  if (components.length > 0 || labels.length > 0) {
    projectFilters.push({
      projectname: name,
      components: components,
      labels: labels
    });
  }
}

({
  boardScopes: JSON.stringify(boardScopes),
  projectKeys: projectKeys,
  hasIssueScope: hasIssueScope,
  projectnames: validProjects.length > 0 ? validProjects : ['__none__'],
  hasProjects: validProjects.length > 0 ? 1 : 0,
  excludeProjects: excludeProjects.length > 0 ? excludeProjects : ['__none__'],
  hasExclude: excludeProjects.length > 0 ? 1 : 0,
  from: from,
  to: to,
  userwhitelist: userwhitelist.length > 0 ? userwhitelist : ['__none__'],
  hasUserwhitelist: userwhitelist.length > 0 ? 1 : 0,
  projectFilters: JSON.stringify(projectFilters)
})

output_script:
var rows = results.main || [];
var projectFilters = JSON.parse(input.projectFilters || '[]');

var issues = [];
for (var i = 0; i < rows.length; i++) {
  var row = rows[i];
  if (projectFilters.length > 0) {
    var hasFilter = false;
    var matched = false;
    for (var j = 0; j < projectFilters.length; j++) {
      var pf = projectFilters[j];
      if (row.project_name !== pf.projectname) continue;
      hasFilter = true;

      var compMatch = pf.components.length === 0;
      if (!compMatch && row.component) {
        for (var k = 0; k < pf.components.length; k++) {
          if (row.component.indexOf(pf.components[k]) >= 0) {
            compMatch = true;
            break;
          }
        }
      }

      var labelMatch = pf.labels.length === 0;
      if (!labelMatch && row.label_names) {
        var labelList = row.label_names.split(',');
        for (var k = 0; k < pf.labels.length; k++) {
          for (var m = 0; m < labelList.length; m++) {
            if (labelList[m] === pf.labels[k]) {
              labelMatch = true;
              break;
            }
          }
          if (labelMatch) break;
        }
      }

      if (pf.components.length > 0 && pf.labels.length > 0) {
        matched = compMatch || labelMatch;
      } else if (pf.components.length > 0) {
        matched = compMatch;
      } else {
        matched = labelMatch;
      }
      break;
    }
    if (hasFilter && !matched) continue;
  }
  issues.push(row);
}

var countByType = {};
var spByType = {};
var totalCount = 0;
var totalSP = 0;
var issuesWithSP = 0;
var nonEpicCount = 0;

for (var i = 0; i < issues.length; i++) {
  var issue = issues[i];
  var rawType = issue.original_type || issue.type || '';
  var typeName;

  if (!rawType || rawType.trim() === '') {
    typeName = 'Other';
  } else if (rawType.indexOf(',') >= 0) {
    var parts = rawType.toLowerCase().split(',');
    var trimmed = [];
    for (var j = 0; j < parts.length; j++) {
      trimmed.push(parts[j].replace(/^\s+|\s+$/g, ''));
    }
    var found = false;
    for (var j = 0; j < trimmed.length; j++) {
      if (trimmed[j] === 'bug') { typeName = 'Bug'; found = true; break; }
    }
    if (!found) {
      for (var j = 0; j < trimmed.length; j++) {
        if (trimmed[j] === 'enhancement' || trimmed[j] === 'feature') {
          typeName = 'Feature'; found = true; break;
        }
      }
    }
    if (!found) {
      for (var j = 0; j < trimmed.length; j++) {
        if (trimmed[j] === 'documentation') { typeName = 'Documentation'; found = true; break; }
      }
    }
    if (!found) {
      for (var j = 0; j < trimmed.length; j++) {
        if (trimmed[j] === 'duplicate') { typeName = 'Duplicate'; found = true; break; }
      }
    }
    if (!found) typeName = 'Other';
  } else {
    typeName = rawType.charAt(0).toUpperCase() + rawType.slice(1);
  }

  countByType[typeName] = (countByType[typeName] || 0) + 1;
  totalCount++;

  if (typeName.toLowerCase() !== 'epic') {
    nonEpicCount++;
    var sp = parseFloat(issue.story_point);
    if (!isNaN(sp) && sp > 0) {
      spByType[typeName] = (spByType[typeName] || 0) + sp;
      totalSP += sp;
      issuesWithSP++;
    }
  }
}

var types = [];
for (var t in countByType) {
  if (countByType.hasOwnProperty(t)) {
    types.push({ name: t, count: countByType[t] });
  }
}
types.sort(function(a, b) { return b.count - a.count; });

var typeColors = {
  'Story': '#92d68a', 'Task': '#a18fff', 'Bug': '#ef9234',
  'Feature': '#7ec8e3', 'Spike': '#f5c97e', 'Incident': '#e09090',
  'Sub-task': '#b8bbbe', 'Initiative': '#7ecbc0'
};
var fallbackColors = ['#8bb4d9', '#c4b0e8', '#a8d4a0', '#e0c499', '#9ac8d6'];
var colorIndex = 0;
var chartLabels = [];
var chartValues = [];
var chartColors = [];
for (var i = 0; i < types.length; i++) {
  chartLabels.push(types[i].name);
  chartValues.push(types[i].count);
  chartColors.push(typeColors[types[i].name] || fallbackColors[colorIndex++ % fallbackColors.length]);
}

var result;
if (totalCount === 0) {
  result = { error: "No resolved issues found for this time period" };
} else {
  result = {
    type: "bar",
    label: "Issue Type Breakdown",
    description: "Resolved issues grouped by Jira issue type (Story, Bug, Task, etc.) for the selected period.",
    data: {
      labels: chartLabels,
      datasets: [{
        label: 'Resolved Issues',
        data: chartValues,
        backgroundColor: chartColors,
        borderRadius: 4,
        barThickness: 28
      }],
      options: {
        indexAxis: 'y',
        plugins: { legend: { display: false } },
        scales: {
          x: {
            beginAtZero: true,
            title: { display: true, text: 'Issue Count' },
            grid: { color: 'rgba(0, 0, 0, 0.1)' }
          },
          y: { grid: { display: false } }
        }
      }
    }
  };
}
result
